class Solution:
    def lemonadeChange(self, bills: list[int]) -> bool:
        states = {(0, 0)}
        for bill in bills:
            following = set()
            for fives, tens in states:
                if bill == 5:
                    following.add((fives + 1, tens))
                elif bill == 10 and fives:
                    following.add((fives - 1, tens + 1))
                elif bill == 20:
                    if fives and tens:
                        following.add((fives - 1, tens - 1))
                    if fives >= 3:
                        following.add((fives - 3, tens))
            states = following
            if not states:
                return False
        return True
